var Fillow = function () {
    "use strict";

    var e = $(window).width();

    var n = function () {
        setTimeout(function () {
            jQuery("#preloader").remove();
            $("#main-wrapper").addClass("show");
        }, 800);
    };

    var a = function () {
        jQuery("#menu").length > 0 &&
            $("#menu").metisMenu();

        jQuery(".metismenu > .mm-active ").each(function () {
            !jQuery(this).children("ul").length > 0 &&
                jQuery(this).addClass("active-no-child");
        });
    };

    var i = function () {
        $("#checkAll").on("change", function () {
            $("td input, .email-list .custom-checkbox input")
                .prop("checked", $(this).prop("checked"));
        });

        $(".checkAllInput").on("click", function () {
            jQuery(this)
                .closest(".ItemsCheckboxSec")
                .find('input[type="checkbox"]')
                .prop("checked", !0);
        });

        $(".unCheckAllInput").on("click", function () {
            jQuery(this)
                .closest(".ItemsCheckboxSec")
                .find('input[type="checkbox"]')
                .prop("checked", !1);
        });
    };

    var l = function () {
        $(".nav-control").on("click", function () {
            $("#main-wrapper").toggleClass("menu-toggle");
            $(".hamburger").toggleClass("is-active");
        });
    };

    var s = function () {
        for (
            var e = window.location,
                t = $("ul#menu a")
                    .filter(function () {
                        return this.href == e;
                    })
                    .addClass("mm-active")
                    .parent()
                    .addClass("mm-active");
            t.is("li");

        ) {
            t = t
                .parent()
                .addClass("mm-show")
                .parent()
                .addClass("mm-active");
        }
    };

    var c = function () {
        $("ul#menu>li").on("click", function () {
            let e = $("body").attr("data-sidebar-style");

            "mini" === e &&
                (
                    console.log($(this).find("ul")),
                    $(this).find("ul").stop()
                );
        });
    };

    var d = function () {
        $('a[data-action="collapse"]').on("click", function (e) {
            e.preventDefault();

            $(this)
                .closest(".card")
                .find('[data-action="collapse"] i')
                .toggleClass(
                    "mdi-arrow-down mdi-arrow-up"
                );

            $(this)
                .closest(".card")
                .children(".card-body")
                .collapse("toggle");
        });

        $('a[data-action="expand"]').on("click", function (e) {
            e.preventDefault();

            $(this)
                .closest(".card")
                .find('[data-action="expand"] i')
                .toggleClass(
                    "icon-size-actual icon-size-fullscreen"
                );

            $(this)
                .closest(".card")
                .toggleClass("card-fullscreen");
        });

        $('[data-action="close"]').on("click", function () {
            $(this)
                .closest(".card")
                .removeClass()
                .slideUp("fast");
        });

        $('[data-action="reload"]').on("click", function () {
            var e = $(this);

            e.parents(".card").addClass("card-load");

            e.parents(".card").append(
                '<div class="card-loader"><i class=" ti-reload rotate-refresh"></div>'
            );

            setTimeout(function () {
                e.parents(".card")
                    .children(".card-loader")
                    .remove();

                e.parents(".card")
                    .removeClass("card-load");
            }, 2000);
        });
    };

    var r = function () {
        let e = $(".header").innerHeight();

        $(window).scroll(function () {
            "horizontal" ===
                $("body").attr("data-layout") &&
                "static" ===
                    $("body").attr("data-header-position") &&
                "fixed" ===
                    $("body").attr("data-sidebar-position") &&
                (
                    $(this.window).scrollTop() >= e
                        ? $(".dlabnav").addClass("fixed")
                        : $(".dlabnav").removeClass("fixed")
                );
        });
    };

    var u = function () {
        e <= 991 &&
            (
                jQuery(".menu-tabs .nav-link").on(
                    "click",
                    function () {
                        jQuery(this).hasClass("open")
                            ? (
                                jQuery(this).removeClass("open"),
                                jQuery(".fixed-content-box")
                                    .removeClass("active"),
                                jQuery(".hamburger").show()
                            )
                            : (
                                jQuery(".menu-tabs .nav-link")
                                    .removeClass("open"),
                                jQuery(this).addClass("open"),
                                jQuery(".fixed-content-box")
                                    .addClass("active"),
                                jQuery(".hamburger").hide()
                            );
                    }
                ),

                jQuery(".close-fixed-content").on(
                    "click",
                    function () {
                        jQuery(".fixed-content-box")
                            .removeClass("active");

                        jQuery(".hamburger")
                            .removeClass("is-active");

                        jQuery("#main-wrapper")
                            .removeClass("menu-toggle");

                        jQuery(".hamburger").show();
                    }
                )
            );
    };

    var f = function () {
        $(".btn-number").on("click", function (e) {
            e.preventDefault();

            fieldName = $(this).attr("data-field");
            type = $(this).attr("data-type");

            var t = $("input[name='" + fieldName + "']");
            var n = parseInt(t.val());

            isNaN(n)
                ? t.val(0)
                : "minus" == type
                    ? t.val(n - 1)
                    : "plus" == type && t.val(n + 1);
        });
    };

    var v = function () {
        $(".custom-file-input").on("change", function () {
            var e = $(this)
                .val()
                .split("\\")
                .pop();

            $(this)
                .siblings(".custom-file-label")
                .addClass("selected")
                .html(e);
        });
    };

    var C = function () {
        $(".dlab-demo-trigger").on("click", function () {
            $(".dlab-demo-panel").addClass("show");
        });

        $(".dlab-demo-close, .bg-close").on(
            "click",
            function () {
                $(".dlab-demo-panel")
                    .removeClass("show");
            }
        );

        $(".dlab-demo-bx").on("click", function () {
            $(".dlab-demo-bx")
                .removeClass("demo-active");

            $(this).addClass("demo-active");
        });
    };

    var w = function () {
        e > 1024 &&
            $(".metismenu li")
                .unbind()
                .each(function () {
                    if ($("ul", this).length > 0) {
                        var t = $("ul:first", this)
                                .css("display", "block"),
                            n = t.offset().left,
                            a = t.width();

                        t = $("ul:first", this)
                            .removeAttr("style");

                        $("body").height();

                        var o = $("body").width();

                        if (jQuery("html").hasClass("rtl"))
                            var i = n + a <= o;
                        else
                            var i = n > 0;

                        i
                            ? $(this)
                                .find("ul:first")
                                .removeClass("left")
                            : $(this)
                                .find("ul:first")
                                .addClass("left");
                    }
                });
    };

    var F = function () {
        $(document).ready(function () {
            $(".email-tools-box").on(
                "click",
                function () {
                    $(" .email-left-body ,.email-tools-box")
                        .toggleClass("active");
                }
            );
        });
    };

    var I = function () {
        jQuery(".SlideToolHeader").on(
            "click",
            function () {
                jQuery(this)
                    .find(".handle")
                    .hasClass("expand")
                    ? (
                        jQuery(this)
                            .find(".handle")
                            .removeClass("expand")
                            .addClass("collapse"),

                        jQuery(this)
                            .closest(".cm-content-box")
                            .find(".cm-content-body")
                            .slideUp(300),

                        jQuery(this)
                            .closest(".content-title")
                            .addClass("collapse")
                    )
                    : (
                        jQuery(this)
                            .find(".handle")
                            .removeClass("collapse")
                            .addClass("expand"),

                        jQuery(this)
                            .closest(".cm-content-box")
                            .find(".cm-content-body")
                            .slideDown(300),

                        jQuery(this)
                            .closest(".content-title")
                            .removeClass("collapse")
                    );
            }
        );

        $(document).ready(function () {
            $(".open").on("click", function () {
                $(".main-check").slideToggle("slow");
            });
        });
    };

    return {
        init: function () {
            a();
            i();
            l();
            s();
            c();
            d();
            r();
            u();
            f();
            v();
            C();
            I();
            F();
        },

        load: function () {
            n();
        },

        handleMenuPosition: function () {
            w();
        }
    };
}();

jQuery(document).ready(function () {
    $('[data-bs-toggle="popover"]').popover();

    "use strict";

    Fillow.init();
});

jQuery(window).on("load", function () {
    "use strict";

    Fillow.load();

    setTimeout(function () {
        Fillow.handleMenuPosition();
    }, 1000);
});

jQuery(window).on("resize", function () {
    "use strict";

    setTimeout(function () {
        Fillow.handleMenuPosition();
    }, 1000);
});